        'kanban_labels_style_options' => [
            'chip' => '带文字的标签',
            'bar' => '仅色条',
        ],
        'description_custom_view_columns' => '选择要在视图中显示的列。',
        'description_custom_view_kanban_columns' => '选择卡片上显示的列。“显示位置”决定在卡片中的显示位置，“显示样式”用于选择单元格外观预设（标记、胶囊、徽章等）。与数据列表使用相同的预设库，因此外观只需定义一次，即可在两个页面上保持一致。<br/>※未选择“显示样式”时遵循列的设置；列也未设置时，以“项目名 + 值”显示。<br/>※“图标”请输入 Font Awesome 的类名（例如 fa-phone）。以逗号分隔多个“值:类名”，即可为每个值设置不同的图标。<br/>※未设置时，卡片仅显示标题。<br/>※被指定为“彩色标签列”“截止日期列（SLA 计时）”“角标列”的列会显示在各自的位置，因此不会在卡片正文中重复显示。',
        'description_custom_view_calendar_columns' => '选择要在日历中显示的日期列。<br/>※如果“目标列”中没有显示自定义列，说明尚未设置<a href="%s" target="_blank">搜索索引<i class="fa fa-external-link"></i></a>。请确认链接目标的内容并进行设置。',
        'description_custom_view_groups' => '设置用于对视图分组的键列。<br />※如果“目标列”中没有显示自定义列，说明尚未设置<a href="%s" target="_blank">搜索索引<i class="fa fa-external-link"></i></a>。请确认链接目标的内容并进行设置。',
        'description_custom_view_summaries' => '设置视图中显示的汇总列。<br/>※汇总对象为“ID”“整数”“小数”“货币”“日期”类型的列。如需统计数据的总条数，请将目标列设为“ID”，汇总类型设为“计数”。',
        'description_custom_view_sorts' => '设置视图中数据的显示顺序。设置两项以上时，如果表的数据量非常大，性能可能会下降。<br />※如果“目标列”中没有显示自定义列，说明尚未设置<a href="%s" target="_blank">搜索索引<i class="fa fa-external-link"></i></a>。请确认链接目标的内容并进行设置。',
        'description_custom_view_filters' => '设置视图中显示数据的条件。<br/>※除此设置外，还会对数据进行筛选，仅显示登录用户拥有权限的数据。<br />※如果“目标列”中没有显示自定义列，说明尚未设置<a href="%s" target="_blank">搜索索引<i class="fa fa-external-link"></i></a>。请确认链接目标的内容并进行设置。',
        'description_custom_view_grid_filters' => '指定在视图顶部的“筛选”中作为选项显示的列。<br/>※如需显示系统默认项目，请不要向此列表添加列。<br/>※如果“目标列”中没有显示自定义列，说明尚未设置<a href="%s" target="_blank">搜索索引<i class="fa fa-external-link"></i></a>。请确认链接目标的内容并进行设置。',
        'description_custom_view_summary_filters' => '<br/>※此“筛选”用于在汇总前缩小数据范围，而不是筛选汇总结果。',
        'help' => [
            'custom_view_type' => '系统视图：使用此表的所有用户都可以使用的视图。用户视图：仅创建者本人可以使用的视图。',
            'grid_preset' => '在数据列表中以所选预设的外观显示此列。<br/>※优先于列的设置。<br/>※点击铅笔按钮可新建或编辑预设。',
            'sort_type' => '指定按升序（从小到大）还是降序（从大到小）排序。',
            'sort_order_summaries' => '对获取的数据进行排序。<br />按“分组列”和“汇总列”中数值从小到大的顺序进行排序。',
            'use_view_infobox' => '设为 YES 后，可以在视图顶部设置信息框，用于填写业务内容或给用户的留言等。',
            'view_infobox_title' => '请输入信息框中显示的标题。',
            'view_infobox' => '请输入信息框中显示的 HTML。※不能输入图片和脚本。',
            'order' => '自定义视图菜单按钮的显示顺序。',
            'kanban_group_column' => '此列的选项将成为看板的列。<br/>※只能指定选项列（非多选）。“看板列的生成方式”为“根据工作流的状态生成”时，不使用此设置。',
            'kanban_swimlane_column' => '按此列的值将看板横向分隔显示。<br/>※未设置时，不分隔显示。',
            'kanban_editable' => '设为 YES 后，将卡片拖到其他列时，会更新“作为看板列的项目”的值。<br/>※没有数据编辑权限的用户，即使设为 YES 也无法拖动。',
            'inline_edit_enabled' => '设为 NO 后，此视图的数据列表不使用行内编辑。批量编辑和数据编辑页面仍可照常使用。<br/>※系统设置中的“在数据列表中使用行内编辑”为 NO 时，即使设为 YES 也无法行内编辑。',
            'kanban_max_count' => '看板上显示的最大数据条数。条数过多会使页面变慢。',
            'gantt_start_column' => '作为条形起始位置的日期列。',
            'gantt_end_column' => '作为条形结束位置的日期列。<br/>※早于今天且进度未满 100 的数据，将以红框显示为“已逾期”。',
            'gantt_color_column' => '按此列的值为条形着色。<br/>※直接使用列的详细设置“列表值颜色”中设定的颜色。',
            'gantt_progress_column' => '在条形内以深色叠加显示进度（%）。',
            'gantt_group_column' => '按此列的值对行进行分组。<br/>※选择引用其他表的列（如里程碑）时，将以引用表的日期列中列名或列显示名包含“期限”“截止”“交期”“due”“deadline”等的列作为截止日期，显示◆标记。没有符合条件的列时，使用最后一个日期列。',
            'gantt_parent_column' => '选择引用本表的列后，子数据将缩进显示在父数据下方。',
            'gantt_assignee_column' => '选择用户列后，将在每行显示头像。',
            'gantt_max_count' => '图表中显示的最大条数（10-2000，默认 500）。',
            'kanban_source' => '选择看板列的生成来源。<br/>・根据选项列的值生成：下方“作为看板列的项目”的选项将直接成为看板列。<br/>・根据工作流的状态生成：应用于此表的工作流的状态将成为看板列。移动卡片时，会打开推进到该状态的工作流操作确认页面。工作流不允许的移动将无法进行。',
            'kanban_wip_enforce' => '决定将卡片移入已达到 WIP 上限的列时的行为。<br/>“允许”…与以前相同。仅标题变红，仍可移动。<br/>“先确认再允许”…显示确认消息，确认后才移动。<br/>“不允许”…拖动时已达上限的列显示为灰色，无法移入。<br/>※未设置 WIP 上限的列不受影响。<br/>※符合“视为加急的值”的卡片不受此限制（遵循看板中插队任务可以超出上限的理念），但仍会计入数量，因此标题上会持续显示已超出上限。',
            'kanban_policies' => '在列标题上显示该列的规则。将鼠标悬停在标记上即可查看内容。<br/>例如：在“测试中”列写上“测试规格书的所有项目都通过后再进入下一步”，所有人都能看到进入下一步的条件。<br/>※“列”只需从表的选项（或工作流的状态）中选择。<br/>※与当前显示的看板列不匹配的设置将被忽略。',
            'kanban_wips' => '为每列设置可同时容纳的卡片数上限。“目标列”只需从表的选项（或工作流的状态）中选择，无需手动输入。<br/>※超出上限的列，标题会变红。<br/>※与当前显示的看板列不匹配的设置将被忽略。<br/>※按卡片数计数时为 1～999。指定“WIP 上限的计数方式（数值列）”时，请输入该项合计的上限（可以大于 999）。',
            'kanban_done_keys' => '从表的选项中选择视为“已完成”的看板列。<br/>※所选列中的数据将停止截止倒计时，并计入汇总栏的“已完成”。<br/>※根据工作流生成时，设为“完成”的状态会自动视为已完成，因此无需在此设置。<br/>※与当前显示的看板列不匹配的设置将被忽略。',
            'kanban_title_column' => '在卡片中以粗体标题显示的列。<br/>※设置后，卡片顶部会以链接形式显示数据的显示名称。<br/>※未设置时，数据的显示名称直接作为标题。',
            'kanban_assignee_column' => '表示负责人的列。<br/>※在卡片底部带头像显示，未填写的卡片显示“未分配”。<br/>※也用于汇总栏的“未分配”、筛选的“仅显示未分配”以及“批量分配”。<br/>※<b>未设置时</b>，不显示头像、汇总栏的“未分配”、筛选的“仅显示未分配”、“批量分配”、卡片上的负责人更改以及“自动分配”。除非另行设置“‘我的’按钮判断所用的列”，否则“我的卡片”按钮也不显示。',
            'kanban_mine_column' => '决定工具栏上的“我的卡片”按钮根据哪一列判断卡片属于您。<br/>※未设置时，使用“负责人列”。如果指定申请人列，则可以只筛选出您提交的请求。<br/>※除用户列和组织列外，还可以指定引用恰好包含一个用户列的表的列（将通过该列自动查找与您关联的行）。<br/>※如果指定的列无法判断查看者是谁（例如普通选项列），则不显示该按钮。',
            'kanban_filter_columns' => '只选择筛选面板中需要显示的列。按选择顺序显示。<br/>※未设置时，将列出看板读取的所有列（可分组的列、负责人、卡片上显示的列等）。列较多的表建议进行筛选。<br/>※关键字搜索、分组、泳道和复选框始终显示，与此设置无关。',
            'kanban_limit_column' => '截止日期列。<br/>※根据与当前时间的差值，在卡片上显示“剩余”“即将到期”或“已逾期”徽章。<br/>※符合“视为已完成的值”的数据显示为“已达成”。<br/>※<b>未设置时</b>，不显示截止徽章、汇总栏的“已逾期”、筛选的“仅显示已逾期”以及卡片上的截止日期更改。',
            'kanban_sum_column' => '在列标题下方显示此数值列的合计。<br/>例如：选择金额后，标题会显示为“董事审批 &yen;34,700,000”，停留在该列的金额一目了然。<br/>※仅用于显示，不影响 WIP 上限。<br/>※千位分隔符和货币符号按该列的设置显示。<br/>※使用筛选后，仅合计屏幕上剩余的卡片。',
            'kanban_blocked_keys' => '选择表示“工作已停滞”的值。带有所选值的卡片会显示红色边框和旗帜标记，KPI 和筛选中会增加“阻塞中”。<br/>例如：选择“状态”列的“暂停”“退回”，或“阻塞中”列的“是”。<br/>※不必是用于分组的列，可以选择任意列的任意值。<br/>※这样可以直观地区分正在推进的工作和已停滞的工作。',
            'kanban_expedite_keys' => '选择表示“插队的最高优先事项”的值。带有所选值的卡片会显示醒目的边框；如果按该列划分泳道，该泳道会固定在最上方。<br/>例如：选择“优先级”列的“紧急”。<br/>※最高优先的卡片不受“移入已满的列”的限制（符合看板中插队可以超出上限的做法）。但仍会计入数量，因此超出上限的情况会保留在标题中。<br/>※将太多值设为最高优先会失去意义，请控制在一两个。',
            'kanban_hide_keys' => '不在看板上显示所选值的列。<br/>例如：选择“完成”“取消”后，已结束的工作会消失，看板上只剩进行中的工作。<br/>※不会读取隐藏列的数据。数据量大的表仅此一项即可大幅加快显示速度。<br/>※也不计入合计、平均值和 KPI。<br/>※对于工作流看板，将记录推进到隐藏的状态后，卡片会从看板上消失（数据本身保留）。<br/>※“未设置”列无法隐藏。<br/>※与当前显示的看板列不匹配的设置将被忽略。',
            'kanban_col_count' => '每列最初加载的卡片数量。<br/>设为 0（留空）时保持原有方式：整个看板最多加载到“最大显示件数”。<br/>设为 50 等值后，每列加载 50 张卡片，列下方会显示“加载更多”按钮。<br/>※此时件数、合计、平均停留天数和 KPI 均按整个表统计，而不是仅统计已加载的卡片。<br/>※数据达到数千条时推荐使用此方式，不再受“最大显示件数”的限制。<br/>※使用视图中设置的泳道划分时，每个单元格（列×泳道）的件数也按整个表统计。<br/>※进行筛选、关键字搜索、更改分组，或在画面上选择其他列作为泳道时，将改为只统计已加载的卡片。',
            'kanban_col_age' => '在列标题下方显示该列卡片平均已停留的天数。<br/>※可以看出工作积压在哪个环节（瓶颈）。<br/>※工作流看板从记录进入该状态的时间开始计算，其他情况从最后更新时间开始计算。',
            'kanban_progress_column' => '在卡片标题下方以进度条显示的数值列（如进度率）。<br/>※0%～49% 为蓝色，50%～99% 为橙色，100% 为绿色。<br/>※值为空的卡片不显示进度条。',
            'kanban_progress_max' => '进度条达到 100% 时对应的值。<br/>例如：百分比（0～100）填 100，共 10 道工序则填 10。<br/>※留空时为 100。',
            'kanban_history' => '在卡片详情面板中显示工作流的审批历史（时间、操作人、操作内容）。<br/>※仅在打开卡片时加载该条记录，不影响看板的显示速度。<br/>※仅在设置了工作流的表中显示。',
            'kanban_wip_column' => 'WIP 上限不按卡片数量，而按此数值列的合计计算。<br/>例如：选择数量后，列标题会显示“1550/1200”这样的合计值和上限。<br/>※不指定时，仍按卡片数量计算。<br/>※只能指定整数、小数、货币列。',
            'kanban_limit_warn' => '距离期限少于此小时数的卡片将显示为“即将到期”（黄色）。<br/>例如：咨询工单填 2（小时），按天计算的交货期填 48（=2天）。<br/>※留空时为 2 小时。',
            'kanban_age_steps' => '按从小到大的顺序输入 3 个用逗号分隔的天数，卡片边框将依次变为黄色、橙色、红色。<br/>例如：1,2,3 → 1天黄色、2天橙色、3天及以上红色；3,7,14 → 适用于较长的流程。<br/>※如果输入的不是 3 个升序数字，则按 1,2,3 处理。',
            'kanban_age_column' => '计算经过天数的基准日期列（如受理日期）。<br/>※卡片左边缘的颜色会随经过天数变化（1天=黄色、2天=橙色、3天及以上=红色）。<br/>※汇总栏的“平均经过天数”也会使用此列。',
            'kanban_ai_column' => '用于推荐负责人的列（如负责小组）。<br/>※对未分配的卡片，推荐在相同值的数据中负责次数最多的人。<br/>※仅当此项和“负责人列”都设置时，才会显示“自动分配”按钮。',
            'kanban_cover_column' => '在卡片顶部作为封面显示的图片列。<br/>※没有图片的数据不显示封面。<br/>※存有多张图片时，使用第一张。<br/>※图片本身请在各数据的编辑画面中上传到此列。',
            'kanban_cover_fit' => '封面图片的显示方式。<br/>※“填充”会铺满整个框，裁剪超出部分。<br/>※“完整显示”会显示整张图片，并留有空白。',
            'kanban_labels_column' => '在卡片顶部以彩色标签显示的选项列。<br/>※也可以指定多选列，此时所有值都会作为标签显示。<br/>※指定的列也会添加到筛选面板中，可筛选出带有任一标签的卡片。',
            'kanban_labels_style' => '标签的外观。<br/>※“标签块”是带文字的小标签，“色条”是只有颜色的细条（Trello 风格）。',
            'kanban_badge_column' => '在卡片右上角以小徽章显示的列（件数、积分、编号等）。<br/>※值为空的数据不显示徽章。',
            'kanban_kpi' => '设为 YES 时，在看板上方显示件数汇总栏。',
            'kanban_quickadd' => '设为 YES 时，每列下方会显示输入框，只需按 Enter 键即可添加数据。<br/>※只会填写显示名称列和该列的值。',
            'kanban_bulk' => '设为 YES 时，可以按 Shift+单击选择多张卡片并批量更改值。',
            'kanban_editform' => '设为 YES 时，单击卡片会在看板上方打开该数据的编辑表单。保存后表单关闭，只更新该卡片。<br/>※没有编辑权限的用户不会显示。<br/>※设为 NO 时，按下方“详情面板”的设置处理。',
            'kanban_drawer' => '设为 YES 时，单击卡片会从右侧打开详情面板。<br/>※设为 NO 时，会跳转到数据的详情页面。<br/>※如果上方的“打开编辑表单”也为 YES，单击会打开编辑表单，详情面板则通过卡片右上角的“i”按钮打开。',
            'kanban_position' => '选择在卡片中的显示位置。',
            'kanban_style' => '以所选预设的样式在卡片上显示此列。<br/>※优先于列的设置。<br/>※可通过铅笔按钮新建或编辑预设。<br/>※未选择时按列的设置显示；列也没有设置时，以“列名＋值”显示。',
            'kanban_icon' => '输入 Font Awesome 的类名（例如：fa-phone）。<br/>如需为每个选项设置不同的图标，请以逗号分隔输入“值:类名”。<br/>例如：phone:fa-phone,mail:fa-envelope,chat:fa-comments',
